div.script:
(function(){
"use strict";
function $(i){return document.getElementById(i);}
var bar=$("bar"),view=$("view"),home=$("home"),st=$("st"),goBtn=$("go"),backBtn=$("back"),
    reloadBtn=$("reload"),openBtn=$("open"),direct=$("direct"),brand=$("brand"),
    errEl=$("err"),errMsg=$("errMsg"),dots=$("dots"),panel=$("panel"),customIn=$("custom"),
    testAllBtn=$("testAll"),panelBtn=$("panelBtn"),saveCustom=$("saveCustom"),
    clearCustom=$("clearCustom"),errDirect=$("errDirect"),errTab=$("errTab"),errRetry=$("errRetry");

var BASE=[
  {n:"cors.dev",       b:function(u){return "https://proxy.cors.dev/"+u;}},
  {n:"allorigins",     b:function(u){return "https://api.allorigins.win/raw?url="+encodeURIComponent(u);}},
  {n:"codetabs",       b:function(u){return "https://api.codetabs.com/v1/proxy?quest="+encodeURIComponent(u);}},
  {n:"cors.lol",       b:function(u){return "https://api.cors.lol/?url="+encodeURIComponent(u);}},
  {n:"thingproxy",     b:function(u){return "https://thingproxy.freeboard.io/fetch/"+u;}},
  {n:"whateverorigin", b:function(u){return "https://whateverorigin.org/get?url="+encodeURIComponent(u);},j:1}
];
var health={};
function ls(k,v){
  try{ if(v===undefined) return localStorage.getItem(k); localStorage.setItem(k,v); }
  catch(e){ return null; }
}
function relays(){
  var l=BASE.slice(), c=ls("vp_custom");
  if(c) l.push({n:"custom",b:function(u){
    return c.replace(/\{raw\}/g,u).replace(/\{url\}/g,encodeURIComponent(u));
  }});
  return l;
}
function ordered(){
  var p=ls("vp_relay");
  return relays().sort(function(a,b){
    function s(r){ return r.n===p?0 : health[r.n]===1?1 : health[r.n]===undefined?2 : 3; }
    return s(a)-s(b);
  });
}
function paintDots(){
  dots.innerHTML="";
  relays().forEach(function(r){
    var h=health[r.n], s=document.createElement("span");
    s.className="rdot"+(h===1?" ok":h===0?" bad":"");
    s.textContent=r.n;
    s.title=r.n+" \u2014 "+(h===1?"reachable":h===0?"unreachable":"untested")+" (click to prefer)";
    s.onclick=function(){ ls("vp_relay",r.n); paintDots(); say("preferred relay: "+r.n); };
    dots.appendChild(s);
  });
}
function to(url,ms){
  return new Promise(function(res,rej){
    var ac=null,done=false;
    try{ ac=new AbortController(); }catch(e){}
    var t=setTimeout(function(){ done=true; if(ac)ac.abort(); rej(new Error("timeout")); },ms);
    fetch(url, ac?{signal:ac.signal,redirect:"follow"}:{redirect:"follow"}).then(function(r){
      if(done)return; clearTimeout(t); res(r);
    },function(e){ if(done)return; clearTimeout(t); rej(e); });
  });
}
function grab(url){
  var list=ordered(), errs=[];
  return new Promise(function(res,rej){
    var i=0;
    (function attempt(){
      if(i>=list.length){ rej(new Error(errs.join("  \u00b7  ")||"no relays")); return; }
      var r=list[i++];
      to(r.b(url),12000).then(function(x){
        if(!x.ok) throw new Error(r.n+" HTTP "+x.status);
        return x.text().then(function(t){
          if(r.j){ var j; try{ j=JSON.parse(t); }catch(e){ throw new Error(r.n+" bad json"); } t=j.contents||""; }
          if(!t||!t.trim()) throw new Error(r.n+" returned nothing");
          health[r.n]=1; paintDots();
          res({body:t, ct:(x.headers.get("content-type")||""), name:r.n, purl:r.b(url)});
        });
      }).catch(function(e){ health[r.n]=0; paintDots(); errs.push((e&&e.message)||"failed"); attempt(); });
    })();
  });
}
function probe(r){
  return to(r.b("https://example.com"),9000).then(function(x){
    if(!x.ok) throw 0; return x.text();
  }).then(function(t){ health[r.n]=(t&&t.length>20)?1:0; })
   .catch(function(){ health[r.n]=0; })
   .then(paintDots);
}
function testAll(){ relays().forEach(probe); }

var INJECT = "<scr"+"ipt>(function(){"+
"function nav(u){try{parent.postMessage({__vp:1,u:String(u)},\"*\")}catch(e){}}"+
"document.addEventListener(\"click\",function(e){"+
"var n=e.target;while(n&&n.nodeType!==1)n=n.parentNode;"+
"var a=null;while(n){if(String(n.tagName||\"\").toUpperCase()===\"A\"){a=n;break}n=n.parentNode}"+
"if(!a)return;var h=a.getAttribute(\"href\")||\"\";"+
"if(!h||h.charAt(0)===\"#\"||/^(javascript|mailto|tel|data|blob):/i.test(h))return;"+
"var t=String(a.target||\"\").toLowerCase();"+
"if(t&&t!==\"_self\"&&t!==\"_top\"&&t!==\"_parent\")return;"+
"e.preventDefault();nav(a.href);},true);"+
"document.addEventListener(\"submit\",function(e){"+
"var f=e.target;if(!f||String(f.tagName||\"\").toUpperCase()!==\"FORM\")return;"+
"try{var u=new URL(f.getAttribute(\"action\")||document.baseURI,document.baseURI);"+
"if(String(f.getAttribute(\"method\")||\"get\").toLowerCase()===\"get\"){"+
"new FormData(f).forEach(function(v,k){u.searchParams.set(k,v)});}"+
"e.preventDefault();nav(u.href);}catch(err){}},true);"+
"})();<\/scr"+"ipt>";

function esc(s){return String(s).replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;");}
function norm(v){
  v=(v||"").trim(); if(!v) return "";
  if(/^[a-z][a-z0-9+.\-]*:\/\//i.test(v)) return v;
  if(/^[\w\-]+(\.[\w\-]+)+(:\d+)?(\/.*)?$/i.test(v)) return "https://"+v;
  return "https://lite.duckduckgo.com/lite/?q="+encodeURIComponent(v);
}
function rewrite(html,base){
  html=html.replace(/<meta[^>]+http-equiv=["']?content-security-policy["']?[^>]*>/gi,"");
  html=html.replace(/<base\b[^>]*>/gi,"");
  html=html.replace(/\b(src|href|srcset)=("|')http:\/\//gi,function(m,a,q){return a+"="+q+"https://";});
  var head='<base href="'+esc(base)+'">'+INJECT;
  if(/<head[^>]*>/i.test(html)) return html.replace(/<head[^>]*>/i,function(m){return m+head;});
  if(/<html[^>]*>/i.test(html)) return html.replace(/<html[^>]*>/i,function(m){return m+"<head>"+head+"</head>";});
  return head+html;
}

var hist=[],pos=-1,seq=0,lastUrl="",watchT=null;
function say(t){ st.textContent=t; }
function watch(){
  clearTimeout(watchT);
  watchT=setTimeout(function(){
    if(direct.checked) return;
    try{
      var d=view.contentDocument; if(!d||!d.documentElement) return;
      var txt=(d.body?d.body.textContent:"").trim();
      var rich=d.querySelector("img,svg,canvas,video,iframe,input,table,form");
      if(d.documentElement.scrollHeight<70 && txt.length<20 && !rich)
        st.textContent += "   \u26a0 page looks blank \u2014 try Direct or open in a new tab";
    }catch(e){}
  },3200);
}
function load(input,record){
  var url=norm(input); if(!url) return;
  lastUrl=url; bar.value=url;
  if(record!==false){ hist=hist.slice(0,pos+1); hist.push(url); pos=hist.length-1; }
  home.classList.add("hidden"); errEl.classList.add("hidden");
  if(direct.checked){ say("direct \u25b8 "+url); view.removeAttribute("srcdoc"); view.src=url; return; }
  var my=++seq;
  say("proxying \u25b8 "+url);
  grab(url).then(function(r){
    if(my!==seq) return;
    var isHtml=/html|xml/i.test(r.ct)||/^\s*(<!doctype\s+html|<html|<head)/i.test(r.body);
    if(isHtml){
      view.removeAttribute("src"); view.srcdoc=rewrite(r.body,url);
      say("ok \u25b8 "+url+"   \u00b7   via "+r.name);
    }else{
      view.removeAttribute("srcdoc"); view.src=r.purl;
      say("raw \u25b8 "+url+"   \u00b7   via "+r.name);
    }
    watch();
  }).catch(function(e){
    if(my!==seq) return;
    say("error \u25b8 "+(e.message||e));
    errMsg.textContent=(e.message||String(e));
    errEl.classList.remove("hidden");
  });
}

goBtn.onclick=function(){ load(bar.value); };
bar.onkeydown=function(e){ if(e.key==="Enter"){ e.preventDefault(); load(bar.value); } };
backBtn.onclick=function(){ if(pos>0){ pos--; bar.value=hist[pos]; load(hist[pos],false); } };
reloadBtn.onclick=function(){ if(lastUrl) load(lastUrl,false); };
openBtn.onclick=function(){ if(lastUrl) window.open(lastUrl,"_blank"); };
direct.onchange=function(){ if(lastUrl) load(lastUrl,false); };
brand.onclick=function(){ home.classList.remove("hidden"); errEl.classList.add("hidden"); };
errRetry.onclick=function(){ if(lastUrl) load(lastUrl,false); };
errDirect.onclick=function(){ direct.checked=true; if(lastUrl) load(lastUrl,false); };
errTab.onclick=function(){ if(lastUrl) window.open(lastUrl,"_blank"); };
testAllBtn.onclick=testAll;
panelBtn.onclick=function(){ panel.classList.toggle("hidden"); };
saveCustom.onclick=function(){ var v=customIn.value.trim(); if(v){ ls("vp_custom",v); say("custom relay saved"); paintDots(); } };
clearCustom.onclick=function(){ try{ localStorage.removeItem("vp_custom"); }catch(e){} customIn.value=""; paintDots(); };

window.addEventListener("message",function(e){
  if(e.source!==view.contentWindow) return;
  var d=e.data; if(d&&d.__vp&&d.u) load(d.u);
});
Array.prototype.forEach.call(document.querySelectorAll("[data-go]"),function(a){
  a.onclick=function(){ load(a.getAttribute("data-go")); };
});

customIn.value=ls("vp_custom")||"";
paintDots();
setTimeout(testAll,300);
})();
